      regs_ok E0 srA R -> know_ok RSEGS E0 M knA -> mstatics H sp0 tid can mem0 M ->
      as_VIS H s0 msF' = mkst (regupd R 10 (errno_ret e)) (Z_to_bv 64 0x1a33a0) M rom -> as_AKREL H s0 (mkCfg msF' mo') ->
      m_fds mo' = m_fds mo0 ->
      realizes asegs (mkCfg msF' mo') (t_die (msg_cannot_open path) (m_fs mo')).
Proof.
